css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .grafico{width: 100%; max-width: 360px; height: auto; display: block; margin: 0 auto;}
.mz .grafico-mini{width: 150px; height: auto; display: block;}
.mz .grafico-titulo{font-family: sans-serif; font-size: 11px; font-weight: 700; text-align: center; margin-bottom: 2px;}
.mz .recuerda{border: 2px solid var(--bosque); border-radius: 10px; padding: 6px 12px; margin-bottom: 10px;}
.mz .recuerda-titulo{font-size: 12.5px; font-weight: 700; margin-bottom: 3px; display: flex; align-items: center; gap: 6px;}
.mz .recuerda-idea{font-size: 12px; margin-bottom: 5px; line-height: 1.3;}
.mz .recuerda-ejemplo{display: flex; justify-content: center; gap: 26px; align-items: center;}
.mz .rec-lectura{font-size: 12.5px; line-height: 1.45; max-width: 300px;}
.mz .e1-wrap{display: grid; grid-template-columns: 1fr auto; gap: 16px; align-items: center;}
.mz .tabla-rellenar{border-collapse: collapse; font-size: 13px;}
.mz .tabla-rellenar th,.mz .tabla-rellenar td{border: 1.5px solid var(--bosque); padding: 4px 12px; text-align: center; font-weight: 700;}
.mz .tabla-rellenar th{background: #f3f3f3; font-size: 11.5px; font-family: sans-serif;}
.mz .tabla-rellenar .cant-hueco{min-width: 75px; height: 36px;}
.mz .preg-lista{display: flex; flex-direction: column; gap: 7px;}
.mz .preg-fila{font-size: 13.5px; line-height: 1.35;}
.mz .preg-hueco-grande{display: inline-block; min-width: 110px; border-bottom: 1.5px solid var(--bosque); height: 16px; vertical-align: middle; margin-left: 4px;}
.mz .preg-hueco-op{display: inline-block; min-width: 150px; border-bottom: 1.5px solid var(--bosque); height: 16px; vertical-align: middle; margin-left: 4px;}
.mz .vf-lista{display: flex; flex-direction: column; gap: 6px;}
.mz .vf-fila{display: flex; justify-content: space-between; align-items: center; gap: 12px; font-size: 13px; line-height: 1.3;}
.mz .vf-pills{display: flex; gap: 8px; flex-shrink: 0;}
.mz .vf-pill{display: inline-flex; align-items: center; justify-content: center; width: 23px; height: 23px; border: 2px solid var(--bosque); border-radius: 50%; font-family: sans-serif; font-weight: 800; font-size: 12px;}
.mz .preg-fila,.mz .rec-lectura,.mz .recuerda-idea{line-height: 1.725 !important;}
